/**
 * Regression lock: generated files in `src/data/` must not churn.
 *
 * Every JSON file under `apps/docs/src/data/` is generated by a script *and*
 * committed to git — the app imports several of them statically, the lock tests
 * read them without running the generators, and `interlace-numbers.json` is
 * copied verbatim into sibling repos. Both halves of that are load-bearing, so
 * the generators must be safe to re-run.
 *
 * They weren't. Each one stamped a wall-clock timestamp (`generatedAt`,
 * `lastUpdated`, `_lastUpdated`, `_cachedAt`, `lastSynced`) into its output and
 * wrote unconditionally, so a regeneration that produced *identical data* still
 * produced a diff. Two ways that bit:
 *
 *   1. Locally: `npm run build` runs sync-plugin-stats + sync-tweet-cache before
 *      `next build`, so any build left the tree dirty and the next `git merge`
 *      aborted with "Your local changes to the following files would be
 *      overwritten by merge" (hit during PR #381).
 *   2. In CI: `docs-data.yml` commits `apps/docs/src/data/` whenever
 *      `git diff --quiet` reports a change — a timestamp-only commit on `main`,
 *      which per CLAUDE.md fires a production deploy for no content change.
 *
 * Two locks below: the helper actually skips bookkeeping-only writes, and no
 * generator bypasses the helper.
 */

import { describe, it, expect } from 'vitest';
import { mkdtempSync, readFileSync, statSync, writeFileSync, readdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve, basename } from 'node:path';
import {
  BOOKKEEPING_KEYS,
  stripBookkeeping,
  writeJsonIfChanged,
} from '../../scripts/lib/write-json-if-changed.ts';

const SCRIPTS_DIR = resolve(__dirname, '../../scripts');

describe('writeJsonIfChanged', () => {
  const tmpFile = () => join(mkdtempSync(join(tmpdir(), 'data-write-lock-')), 'out.json');

  it('writes when the file does not exist yet', () => {
    const file = tmpFile();
    expect(writeJsonIfChanged(file, { totalRules: 501 })).toBe(true);
    expect(JSON.parse(readFileSync(file, 'utf-8'))).toEqual({ totalRules: 501 });
  });

  it('writes when content changed', () => {
    const file = tmpFile();
    writeJsonIfChanged(file, { totalRules: 501, generatedAt: '2026-08-01' });
    expect(writeJsonIfChanged(file, { totalRules: 502, generatedAt: '2026-08-01' })).toBe(true);
    expect(JSON.parse(readFileSync(file, 'utf-8')).totalRules).toBe(502);
  });

  // The mtime and content halves are separate tests on purpose: a `statSync`
  // followed by a `readFileSync` on the same path is a check-then-use pattern,
  // and CodeQL's js/file-system-race flags it (high severity) even in a test
  // against a fresh tmpdir. Each test touches the file one way only.
  it('does not touch the file when only a top-level timestamp moved', () => {
    const file = tmpFile();
    writeJsonIfChanged(file, { totalRules: 501, generatedAt: '2026-08-01' });
    const before = statSync(file).mtimeMs;

    expect(writeJsonIfChanged(file, { totalRules: 501, generatedAt: '2026-08-04' })).toBe(false);
    expect(statSync(file).mtimeMs).toBe(before);
  });

  it('leaves the old timestamp in the file when it skips the write', () => {
    const file = tmpFile();
    writeJsonIfChanged(file, { totalRules: 501, generatedAt: '2026-08-01' });
    writeJsonIfChanged(file, { totalRules: 501, generatedAt: '2026-08-04' });

    expect(JSON.parse(readFileSync(file, 'utf-8')).generatedAt).toBe('2026-08-01');
  });

  it('ignores timestamps nested inside entries (the cached-tweets regression)', () => {
    // sync-tweet-cache re-fetches after a 7-day TTL and re-stamps `_cachedAt`
    // on every tweet. Comparing that field made every post-TTL build rewrite
    // the cache even when Twitter returned byte-identical tweets.
    const file = tmpFile();
    const cache = (cachedAt: string) => ({
      tweets: { '2006790779537121585': { text: 'hi', user: { name: 'Ofri' }, _cachedAt: cachedAt } },
      _lastUpdated: cachedAt,
    });

    writeJsonIfChanged(file, cache('2026-07-31T02:29:36.206Z'));
    const before = statSync(file).mtimeMs;

    expect(writeJsonIfChanged(file, cache('2026-08-09T09:00:00.000Z'))).toBe(false);
    expect(statSync(file).mtimeMs).toBe(before);
  });

  it('still writes when a nested entry actually changed', () => {
    const file = tmpFile();
    writeJsonIfChanged(file, { tweets: { a: { text: 'hi', _cachedAt: 'x' } } });
    expect(writeJsonIfChanged(file, { tweets: { a: { text: 'bye', _cachedAt: 'x' } } })).toBe(true);
  });

  it('writes over an unparseable file instead of throwing', () => {
    const file = tmpFile();
    writeFileSync(file, '{ truncated');
    expect(writeJsonIfChanged(file, { ok: true })).toBe(true);
  });

  it('strips bookkeeping keys at every depth, leaving everything else intact', () => {
    expect(
      stripBookkeeping({
        rules: [{ name: 'no-eval', lastSynced: 'now' }],
        meta: { generatedAt: 'now', source: 'local-lcov' },
        total: 1,
      }),
    ).toEqual({ rules: [{ name: 'no-eval' }], meta: { source: 'local-lcov' }, total: 1 });
  });

  it('covers every timestamp key the generators actually emit', () => {
    // Non-vacuity guard: if a generator starts stamping a new timestamp field,
    // this fails rather than silently letting the churn back in.
    // Both shapes count: the object-literal form (`generatedAt: new Date()…`)
    // and the assignment form (`cache._lastUpdated = new Date()…`), which
    // sync-tweet-cache and sync-devto-cache use.
    const emitted = new Set<string>();
    for (const file of readdirSync(SCRIPTS_DIR).filter((f) => f.endsWith('.ts'))) {
      const source = readFileSync(join(SCRIPTS_DIR, file), 'utf-8');
      for (const [, key] of source.matchAll(
        /(?:^\s*|\.)(\w+)\s*[:=]\s*new Date\(\)\.toISOString\(\)/gm,
      )) {
        emitted.add(key);
      }
    }
    // Both shapes must actually be present, or the regex could rot into one
    // that matches nothing and this assertion would pass on an empty set.
    expect(emitted).toContain('generatedAt'); // object-literal form
    expect(emitted).toContain('_lastUpdated'); // assignment form
    expect([...emitted].filter((key) => !BOOKKEEPING_KEYS.includes(key))).toEqual([]);
  });
});

describe('committed src/data files match what the helper writes', () => {
  // The helper writes `JSON.stringify(data, null, 2)` with no trailing newline.
  // If the committed bytes ever drift from that — a hand-edit, an editor adding
  // a final newline, a formatter changing the indent — the very next generator
  // run rewrites the file to reformat it, which is the churn this PR removes,
  // just arriving one commit later. Locking the exact serialization is what
  // makes "no trailing newline" a checked invariant instead of a comment.
  // `schemas/` is excluded: those are hand-written JSON Schema, not generated.
  const DATA_DIR = resolve(__dirname, '../data');
  const walk = (dir: string): string[] =>
    readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) return entry.name === 'schemas' ? [] : walk(full);
      return entry.name.endsWith('.json') ? [full] : [];
    });
  const files = walk(DATA_DIR);

  it('found the committed data files', () => {
    expect(files.length).toBeGreaterThanOrEqual(6);
  });

  it.each(files.map((f) => [f.slice(DATA_DIR.length + 1), f]))(
    '%s is exactly JSON.stringify(…, null, 2), no trailing newline',
    (_name, full) => {
      const raw = readFileSync(full, 'utf-8');
      expect(raw).toBe(JSON.stringify(JSON.parse(raw), null, 2));
    },
  );
});

describe('src/data generators route every write through writeJsonIfChanged', () => {
  /** Scripts that resolve a path inside `src/data` — i.e. the generators. */
  const generators = readdirSync(SCRIPTS_DIR)
    .filter((file) => file.endsWith('.ts') && !file.endsWith('.test.ts'))
    .map((file) => ({ file, source: readFileSync(join(SCRIPTS_DIR, file), 'utf-8') }))
    .filter(({ source }) => source.includes('src/data'));

  it('found the generators (guards against an empty scan passing vacuously)', () => {
    expect(generators.map((g) => basename(g.file)).sort()).toEqual([
      'sync-devto-cache.ts',
      'sync-plugin-stats.ts',
      'sync-readme-rules.ts',
      'sync-tweet-cache.ts',
      'update-articles-data.ts',
      'update-coverage-stats.ts',
    ]);
  });

  it.each(generators.map((g) => g.file))('%s has no bare writeFileSync call', (file) => {
    const source = readFileSync(join(SCRIPTS_DIR, file), 'utf-8');
    expect(source).not.toMatch(/\b(?:fs\.)?writeFile(?:Sync)?\s*\(/);
  });

  it.each(generators.map((g) => g.file))('%s imports writeJsonIfChanged', (file) => {
    const source = readFileSync(join(SCRIPTS_DIR, file), 'utf-8');
    expect(source).toContain('writeJsonIfChanged');
  });
});
